<?php require 'includes/db.php';if(empty($_SESSION['user_id'])){$_SESSION['after_login']='my-orders.php';flash('warning','Please log in to view your orders.');redirect('login.php');}$uid=(int)$_SESSION['user_id'];$s=$conn->prepare('SELECT id,total,status,created_at FROM orders WHERE user_id=? ORDER BY id DESC');$s->bind_param('i',$uid);$s->execute();$orders=stmt_result($s);$pageTitle='My Orders | J.K BAGS';require 'includes/header.php';?><section class="section white"><div class="container narrow"><div class="heading"><p class="eyebrow">YOUR ACCOUNT</p><h2>My Orders</h2><span></span></div><?php if(!$orders->num_rows):?><div class="empty"><i class="fa-solid fa-box-open"></i><h3>No orders yet</h3><a class="btn-gold" href="products.php">EXPLORE BAGS</a></div><?php else:while($o=$orders->fetch_assoc()):?><article class="order-card"><div class="order-card-head"><div><strong>Order #<?=$o['id']?></strong><div class="small text-muted"><?=e(date('d M Y, g:i A',strtotime($o['created_at'])))?></div></div><div><strong><?=money($o['total'])?></strong><div>Status: <span class="badge text-bg-secondary"><?=e($o['status'])?></span></div></div></div><?php $x=$conn->prepare('SELECT oi.quantity,oi.price,p.name FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?');$x->bind_param('i',$o['id']);$x->execute();$its=stmt_result($x);while($it=$its->fetch_assoc()):?><div class="d-flex justify-content-between small mt-2"><span><?=e($it['name'])?> × <?=$it['quantity']?></span><span><?=money($it['price']*$it['quantity'])?></span></div><?php endwhile;?></article><?php endwhile;endif;?></div></section><?php require 'includes/footer.php';?>
